schema_ddl:
CREATE TABLE aree_funzionali (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome_dipartimento TEXT NOT NULL,
    codice_sede TEXT
);

CREATE TABLE dipendenti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome TEXT NOT NULL,
    cognome TEXT NOT NULL,
    email TEXT UNIQUE,
    dipartimento_id INT REFERENCES aree_funzionali(id) ON DELETE SET NULL
);

CREATE TABLE contratti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    dipendente_id INT NOT NULL REFERENCES dipendenti(id) ON DELETE CASCADE,
    tipo_contratto TEXT NOT NULL CHECK (tipo_contratto IN ('tempo_indeterminato', 'tempo_determinato', 'apprendistato')),
    data_inizio DATE NOT NULL,
    data_fine DATE
);
